// Termite - Reads the state table generated by carpenter and carries out fused lexer/parser.
const std = @import("std");
const stdbits = std.bit_set;
pub const BitSet128 = stdbits.IntegerBitSet(128);
const bitset = @import("../bitset.zig");
const ParsedQueue = @import("tokenqueue.zig").ParsedQueue;

const tok = @import("token.zig");
const token = tok.token;
const q = @import("../queue.zig");
const tbl = @import("table.zig");
const Table = tbl.Table;

const Token = tok.Token;
// const TK = tok.Kind;
pub const TokenQueue = q.Queue(Token, Token.lex(tbl.STREAM_END, 0, 0));

const SYNTAX_Q: u1 = 0;
const AUX_Q: u1 = 1;
const MAX_LITERAL_NUMBER: u64 = 1 << 16; // 65536

pub const MemError = std.mem.Allocator.Error;

pub fn Termite(comptime table: Table) type {
    return struct {
        const Self = @This();
        // pub const OpFn = *const fn (*Self, Table.State) MemError!void;

        buffer: []const u8,
        syntaxQ: *TokenQueue,
        auxQ: *TokenQueue,
        prevToken: Token,
        index: u32,
        tokenStart: u32,
        parsedQ: *ParsedQueue,
        parseState: Table.State,

        // const ops = std.EnumArray(Table.Op, OpFn).initDefault(err, .{
        //     .none = none,
        //     .emit = emit,
        //     .emit_aux = emitAux,
        //     .emit_int = emitInt,
        //     .emit_end = emitEnd,
        //     .emit_sym = emitSym,
        //     .emit_val = emitVal,
        //     .push_op = pushOp,
        //     .flush_all = flushAll,
        //     .err = err,
        // });

        inline fn runOp(self: *Self, comptime state: Table.State) MemError!void {
            switch (state.op) {
                .emit => try self.emit(state),
                .emit_aux => try self.emitAux(state),
                .emit_int => try self.emitInt(state),
                .emit_end => try self.emitEnd(state),
                .emit_sym => try self.emitSym(state),
                .emit_val => try self.emitVal(state),
                .push_op => try self.pushOp(state),
                .push_prefix_op => try self.pushPrefixOp(state),
                .flush_all => try self.flushAll(state),
                .err => try self.err(state),
                .none => try self.none(state),
            }
        }

        pub fn init(buffer: []const u8, syntaxQ: *TokenQueue, auxQ: *TokenQueue, parsedQ: *ParsedQueue) Self {
            const start = Token.lex(tbl.STREAM_START, 0, 0);
            parsedQ.precedenceStack.appendAssumeCapacity(start);
            return Self{
                .buffer = buffer,
                .syntaxQ = syntaxQ,
                .auxQ = auxQ,
                .parsedQ = parsedQ,
                .prevToken = start,
                .index = 0,
                .tokenStart = 0,
                .parseState = table.states[table.parserStartId],
            };
        }

        fn flushPrev(self: *Self, nextSyntax: bool) !void {
            const isSyntax = self.prevToken.kind < table.auxStart;
            if (isSyntax) {
                self.prevToken.flags.alt = !nextSyntax;
                try self.syntaxQ.pushDynamic(self.prevToken);
                try self.genParse();
            } else {
                self.prevToken.flags.alt = nextSyntax;
                try self.auxQ.pushDynamic(self.prevToken);
            }
        }

        fn emitToken(self: *Self, t: Token) MemError!void {
            try self.flushPrev(true);
            self.prevToken = t;
            self.tokenStart = self.index;
        }

        fn emitVal(self: *Self, _: Table.State) MemError!void {
            try self.parsedQ.emit(self.prevToken);
        }

        fn emit(self: *Self, state: Table.State) !void {
            // Pre: token being emitted should be a syntax token
            // std.debug.assert(@backingInt(v.kind) < tok.AUX_KIND_START);
            const t = token(state.arg);
            try self.emitToken(t);
            // self.QIdx[SYNTAX_Q] += 1;
        }

        fn emitAux(self: *Self, state: Table.State) !void {
            try self.emitAuxHelper(state.arg);
        }

        fn emitAuxHelper(self: *Self, arg: u8) !void {
            const t = token(arg);
            try self.flushPrev(false);
            self.prevToken = t;
            self.tokenStart = self.index;
        }

        fn emitInt(self: *Self, state: Table.State) !void {
            const value: u64 = std.fmt.parseInt(u64, self.buffer[self.tokenStart..self.index], 10) catch 0;
            std.debug.assert(value <= MAX_LITERAL_NUMBER);
            const len = self.index - self.tokenStart;
            try self.emitToken(Token.lex(state.arg, @truncate(value), @truncate(len)));
        }

        fn emitEnd(self: *Self, _: Table.State) !void {
            try self.emitAuxHelper(tbl.STREAM_END);
            try self.flushPrev(false);
            try self.genParse();
        }

        fn emitSym(self: *Self, state: Table.State) !void {
            const bitmap = std.mem.readInt(u128, table.transitions[state.transition_id..][0..16], .little);
            // TODO: Init BitSet128 from the transitions
            // const chIndex: u7 = index128(bitset, ch);
            const tokKind = @as(u8, bitset.index128(BitSet128{ .mask = bitmap }, self.buffer[self.tokenStart])) + state.arg;
            try self.emitToken(Token.lex(tokKind, 0, 0));
        }

        fn none(_: *Self, _: Table.State) !void {}
        fn err(_: *Self, _: Table.State) !void {
            std.debug.assert(false);
        }

        fn flush(self: *Self, comptime currentState: Table.State) MemError!Table.State {
            try self.parsedQ.flush(comptime table.popSet(currentState));
            const nextStateId = table.next(currentState, self.parsedQ.top());
            return table.states[nextStateId];
        }

        fn pushOp(self: *Self, comptime currentState: Table.State) !void {
            // const bottom: u7 = @truncate(@backingInt(TK.aux_stream_start));
            // self.parseState = table.states[table.next(state, bottom)];
            self.parseState = try self.flush(currentState);
            try self.parsedQ.pushOp(self.prevToken, self.syntaxQ.tail);
        }

        fn pushPrefixOp(self: *Self, currentState: Table.State) !void {
            var t = self.prevToken;
            t.kind = currentState.arg;
            try self.parsedQ.pushOp(t, self.syntaxQ.tail);
        }

        fn flushAll(self: *Self, comptime state: Table.State) !void {
            self.parseState = try self.flush(state);
        }

        // fn op(self: *Self, state: Table.State) !void {
        //     try ops.get(state.op)(self, state);
        // }

        // pub fn parse(self: *Self) MemError!void {
        //     const tokenKind = self.prevToken.kind;
        //     const nextStateId = table.next(self.parseState, @truncate(@backingInt(tokenKind)));
        //     self.parseState = table.states[nextStateId];
        //     try self.op(self.parseState);
        // }

        pub fn genParse(self: *Self) MemError!void {
            @setEvalBranchQuota(table.states.len * 128 * 8);
            const tokenKind: u7 = @truncate(self.prevToken.kind);
            inline for (table.states) |state| {
                if (self.parseState == state) {
                    const targets = comptime table.targets(state);
                    switch (table.nextStateId(state, tokenKind)) {
                        inline 0...targets.len - 1 => |i| {
                            const next = comptime table.states[targets[i]];
                            self.parseState = next;
                            return self.runOp(next);
                            // return @call(.always_inline, comptime self.runOp(next), .{ self, next });
                        },
                        else => unreachable,
                    }
                }
            }
            unreachable;
        }

        //         pub fn lex(self: *Self) !void {
        //             var state = table.states[0];
        //             while (self.index < self.buffer.len) {
        //                 const ch = self.buffer[self.index];
        //                 // Error on invalid or non-ascii bytes
        //                 std.debug.assert(ch < 0x80);
        //                 // const ch = if (self.index == self.buffer.len) 0 else ;
        //
        //                 const nextStateId = table.next(state, @truncate(ch));
        //                 state = table.states[nextStateId];
        //                 if (state.consume) {
        //                     self.index += 1;
        //                 }
        //
        //                 try self.op(state);
        //                 if (state.op == .emit_end) return;
        //             }
        //             unreachable;
        //         }

        pub fn genLex(self: *Self) !void {
            @setEvalBranchQuota(table.states.len * 128 * 8);
            s: switch (@as(u8, 0)) {
                inline 0...table.states.len - 1 => |id| {
                    const state = comptime table.states[id];
                    if (state.consume) self.index += 1;
                    // try (comptime ops.get(state.op))(self, state);
                    try self.runOp(state);
                    if (state.op == .emit_end) return;

                    const ch = self.buffer[self.index];
                    std.debug.assert(ch < 0x80);

                    const targets = comptime table.targets(state);
                    switch (table.nextStateId(state, @truncate(ch))) {
                        inline 0...targets.len - 1 => |i| continue :s comptime targets[i],
                        else => unreachable,
                    }
                },
                else => unreachable,
            }
        }
    };
}
